//! Byte-for-byte conformance against `reference/vectors/06-spartan/`
//! (`next_mle.json`, `simd_spartan_bin.json`,
//! `virtual_spartan_toy.json`), generated by
//! `reference/gen_vectors_05_06.py`. The Virtual Spartan replay mirrors
//! `reference/tests/test_vectors_05_06.py::test_vsp_replay`; in
//! addition, both Spartan vectors are reproduced by re-proving from
//! the recorded witness rows and comparing every proof element.

mod common;

use std::path::PathBuf;

use om_field::K;
use om_spartan::spartan::{CrossStep, Segment, SegmentKind, SpartanProof, next_mle, prove, verify};
use om_sumcheck::SumcheckProof;
use om_transcript::Transcript;
use serde_json::Value;

fn load(name: &str) -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../reference/vectors/06-spartan")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    serde_json::from_str(&text).unwrap()
}

fn k(v: &Value) -> K {
    K::from_hex(v.as_str().unwrap()).unwrap()
}

fn ks(v: &Value) -> Vec<K> {
    v.as_array().unwrap().iter().map(k).collect()
}

fn msgs(v: &Value) -> Vec<Vec<K>> {
    v.as_array().unwrap().iter().map(ks).collect()
}

fn hexes(xs: &[K]) -> Vec<String> {
    xs.iter().map(|x| x.to_hex()).collect()
}

fn w_rows(v: &Value) -> Vec<Vec<bool>> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|row| row.as_str().unwrap().bytes().map(|c| c == b'1').collect())
        .collect()
}

fn bit_vec(v: &Value) -> Vec<bool> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|b| b.as_u64().unwrap() == 1)
        .collect()
}

#[test]
fn next_mle_vectors() {
    let v = load("next_mle.json");
    for vec in v["vectors"].as_array().unwrap() {
        let s = vec["s"].as_u64().unwrap() as usize;
        let (a, b) = (ks(&vec["a"]), ks(&vec["b"]));
        assert_eq!(a.len(), s);
        assert_eq!(b.len(), s);
        assert_eq!(next_mle(&a, &b).to_hex(), vec["next"].as_str().unwrap());
    }
}

#[test]
fn simd_spartan_bin_vector() {
    let v = load("simd_spartan_bin.json");
    let vec = &v["vectors"][0];
    let label = vec["protocol_label"].as_str().unwrap().as_bytes();
    let prefix = vec["prefix"].as_str().unwrap().as_bytes();
    let q = vec["q"].as_u64().unwrap() as usize;
    let rels = common::structs();
    let rels = &rels[..1];
    let w = w_rows(&vec["W_rows"]);
    let x: Vec<Vec<K>> = vec![Vec::new(); q];

    // Re-prove from the recorded witness and compare every element.
    let mut t = Transcript::new_default(label);
    let (proof, claims) = prove(rels, &w, &x, &mut t, prefix, None, None, None, false);
    assert_eq!(proof.outer_msgs[0], msgs(&vec["outer_msgs"]));
    assert_eq!(proof.outer_finals[0], ks(&vec["outer_finals"]));
    assert_eq!(proof.inner.round_msgs, msgs(&vec["inner_msgs"]));
    assert_eq!(proof.v_w.to_hex(), vec["v_W"].as_str().unwrap());
    assert_eq!(hexes(&claims[0].point), {
        let p: Vec<String> = vec["claim"]["point"]
            .as_array()
            .unwrap()
            .iter()
            .map(|h| h.as_str().unwrap().to_string())
            .collect();
        p
    });
    assert_eq!(
        claims[0].value.to_hex(),
        vec["claim"]["value"].as_str().unwrap()
    );
    assert_eq!(
        t.challenge_k(b"vec/final").to_hex(),
        vec["transcript_final"].as_str().unwrap()
    );

    // Replay: verify the recorded proof.
    let recorded = SpartanProof {
        outer_msgs: vec![msgs(&vec["outer_msgs"])],
        outer_finals: vec![ks(&vec["outer_finals"])],
        inner: SumcheckProof {
            round_msgs: msgs(&vec["inner_msgs"]),
        },
        v_w: k(&vec["v_W"]),
        seg_vals: Vec::new(),
        xs_proof: None,
        xs_vals: None,
    };
    let mut t = Transcript::new_default(label);
    let out = verify(rels, 2, &x, &recorded, &mut t, prefix, None, None, None).unwrap();
    assert_eq!(out.len(), 1);
    assert_eq!(
        out[0].value.to_hex(),
        vec["claim"]["value"].as_str().unwrap()
    );
    assert_eq!(
        t.challenge_k(b"vec/final").to_hex(),
        vec["transcript_final"].as_str().unwrap()
    );
}

#[test]
fn virtual_spartan_toy_vector() {
    let v = load("virtual_spartan_toy.json");
    let vec = &v["vectors"][0];
    let label = vec["protocol_label"].as_str().unwrap().as_bytes();
    let q = vec["q"].as_u64().unwrap() as usize;
    assert_eq!(vec["rho"].as_u64().unwrap() as usize, common::RHO);
    assert_eq!(vec["nu"].as_u64().unwrap() as usize, common::NU);
    let segs: Vec<Segment> = vec["segments"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| Segment {
            seg_id: s[0].as_i64().unwrap(),
            kind: SegmentKind::from_name(s[1].as_str().unwrap()).unwrap(),
            log_cols: s[2].as_u64().unwrap() as usize,
            block: s[3].as_u64().unwrap() as usize,
        })
        .collect();
    let cross = CrossStep {
        in_id: vec["cross_step"]["in_id"].as_i64().unwrap(),
        out_id: vec["cross_step"]["out_id"].as_i64().unwrap(),
        init: bit_vec(&vec["init"]),
        fin: bit_vec(&vec["fin"]),
    };
    let x: Vec<Vec<K>> = vec![Vec::new(); q];
    let rels = common::structs();

    // Re-prove from the recorded witness and compare every element.
    let w = w_rows(&vec["W_rows"]);
    let mut t = Transcript::new_default(label);
    let (proof, claims) = prove(
        &rels,
        &w,
        &x,
        &mut t,
        b"vsp",
        None,
        Some(&segs),
        Some(&cross),
        false,
    );
    for (ti, name) in ["bin", "fld"].into_iter().enumerate() {
        assert_eq!(proof.outer_msgs[ti], msgs(&vec["outer_msgs"][name]));
        assert_eq!(proof.outer_finals[ti], ks(&vec["outer_finals"][name]));
    }
    assert_eq!(proof.inner.round_msgs, msgs(&vec["inner_msgs"]));
    assert_eq!(proof.v_w.to_hex(), vec["v_W"].as_str().unwrap());
    assert_eq!(proof.seg_vals, ks(&vec["seg_vals"]));
    assert_eq!(
        proof.xs_proof.as_ref().unwrap().round_msgs,
        msgs(&vec["xs_msgs"])
    );
    assert_eq!(proof.xs_vals.as_ref().unwrap(), &ks(&vec["xs_vals"]));
    for (c, recorded) in claims.iter().zip(vec["claims"].as_array().unwrap()) {
        assert_eq!(c.comp_id, recorded["id"].as_i64().unwrap());
        assert_eq!(c.point, ks(&recorded["point"]));
        assert_eq!(c.value.to_hex(), recorded["value"].as_str().unwrap());
    }
    assert_eq!(
        t.challenge_k(b"vec/final").to_hex(),
        vec["transcript_final"].as_str().unwrap()
    );

    // Replay exactly as test_vectors_05_06.py::test_vsp_replay.
    let recorded = SpartanProof {
        outer_msgs: ["bin", "fld"]
            .iter()
            .map(|n| msgs(&vec["outer_msgs"][n]))
            .collect(),
        outer_finals: ["bin", "fld"]
            .iter()
            .map(|n| ks(&vec["outer_finals"][n]))
            .collect(),
        inner: SumcheckProof {
            round_msgs: msgs(&vec["inner_msgs"]),
        },
        v_w: k(&vec["v_W"]),
        seg_vals: ks(&vec["seg_vals"]),
        xs_proof: Some(SumcheckProof {
            round_msgs: msgs(&vec["xs_msgs"]),
        }),
        xs_vals: Some(ks(&vec["xs_vals"])),
    };
    let mut t = Transcript::new_default(label);
    let out = verify(
        &rels,
        2,
        &x,
        &recorded,
        &mut t,
        b"vsp",
        None,
        Some(&segs),
        Some(&cross),
    )
    .unwrap();
    let values: Vec<String> = out.iter().map(|c| c.value.to_hex()).collect();
    let recorded_values: Vec<String> = vec["claims"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c["value"].as_str().unwrap().to_string())
        .collect();
    assert_eq!(values, recorded_values);
    assert_eq!(
        t.challenge_k(b"vec/final").to_hex(),
        vec["transcript_final"].as_str().unwrap()
    );
}
